            new Quote { Id = "https://en.wikiquote.org/wiki/Flannery_O'Connor", Text = "No art is sunk in the self, but rather, in art the self becomes self-forgetful in order to meet the demands of the thing seen and the thing being made.", Author = "Flannery O'Connor" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Flannery_O'Connor", Text = "There may never be anything new to say, but there is always a new way to say it, and since, in art, the way of saying a thing becomes a part of what is said, every work of art is unique and requires fresh attention.", Author = "Flannery O'Connor" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Flannery_O'Connor", Text = "The beginning of human knowledge is through the senses, and the fiction writer begins where the human perception begins. He appeals through the senses, and you cannot appeal through the senses with abstractions.", Author = "Flannery O'Connor" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Flannery_O'Connor", Text = "Fiction is about everything human and we are made out of dust, and if you scorn getting yourself dusty, then you shouldn't write fiction. It isn't grand enough for you.", Author = "Flannery O'Connor" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Flannery_O'Connor", Text = "I don't think you should write something as long as a novel around anything that is not of the gravest concern to you and everybody else and for me this is always the conflict between an attraction for the Holy and the disbelief in it that we breathe in with the air of the times.", Author = "Flannery O'Connor" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Flannery_O'Connor", Text = "All human nature vigorously resists grace because grace changes us and the change is painful.", Author = "Flannery O'Connor" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Flannery_O'Connor", Text = "I come from a family where the only emotion respectable to show is irritation. In some this tendency produces hives, in others literature, in me both.", Author = "Flannery O'Connor" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Flannery_O'Connor", Text = "It is hard to make your adversaries real people unless you recognize yourself in them - in which case, if you don't watch out, they cease to be adversaries.", Author = "Flannery O'Connor" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Flannery_O'Connor", Text = "The novel is an art form and when you use it for anything other than art, you pervert it... If you manage to use it successfully for social, religious, or other purposes, it is because you make it art first.", Author = "Flannery O'Connor" },
